def choose_move(observation):
    wx, wy = observation['grid_width'], observation['grid_height']
    x, y = observation['self_position']
    resources = observation.get('resources', [])
    opp = observation.get('opponent_position', [x,y])
    obstacles = set(observation.get('obstacles', []))
    def dist(a, b): return abs(a[0]-b[0])+abs(a[1]-b[1])
    target = None
    if resources:
        target = min(resources, key=lambda p: dist(p, (x,y)))
    else:
        target = None
    def move_towards(tx, ty):
        dx = dy = 0
        if x < tx: dx=1
        elif x > tx: dx=-1
        if y < ty: dy=1
        elif y > ty: dy=-1
        return dx, dy
    if target:
        dx, dy = move_towards(target[0], target[1])
    else:
        dx, dy = 0,0
    nx, ny = x+dx, y+dy
    if (nx, ny) in obstacles or nx<0 or ny<0 or nx>=wx or ny>=wy:
        dx, dy = 0,0
        for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
            nnx, nny = x+ddx, y+ddy
            if (0<=nnx<wx and 0<=nny<wy and (nnx,nny) not in obstacles):
                dx, dy = ddx, ddy
                break
    return [dx, dy]
